actions.script:
const now = new Date()
const pad = (n) => String(n).padStart(2, '0')
const current = `${now.getFullYear()}-${pad(now.getMonth() + 1)}`
const monthText = month && /^\d{4}-\d{2}$/.test(String(month)) ? String(month) : current
const year = Number(monthText.slice(0, 4)), monthNum = Number(monthText.slice(5, 7))
const dayCount = new Date(year, monthNum, 0).getDate()
// kinds map to semantic colors in the component: meeting primary, call info, deadline warning, done positive
const ev = (day, startHour, endHour, title, kind) => ({ id: `${monthText}-${pad(day)}-${kind}-${startHour}`, title, kind,
    start: `${monthText}-${pad(Math.min(day, dayCount))} ${pad(startHour)}:00`, end: `${monthText}-${pad(Math.min(day, dayCount))} ${pad(endHour)}:00` })
const events = [
    ev(2, 9, 10, 'Pipeline review', 'meeting'), ev(2, 14, 15, 'Call Acme about the renewal', 'call'),
    ev(5, 17, 18, 'Quote Q-10077 due', 'deadline'), ev(9, 11, 12, 'Beta Inc. discovery call', 'call'),
    ev(12, 9, 17, 'Trade show, hall 3', 'meeting'), ev(13, 9, 17, 'Trade show, hall 3', 'meeting'),
    ev(16, 10, 11, 'Invoice INV-2201 paid', 'done'), ev(19, 15, 16, 'Delta Corp. demo', 'meeting'),
    ev(23, 17, 18, 'Proposal to Kappa due', 'deadline'), ev(26, 9, 10, 'Monthly close', 'done'),
    ev(28, 13, 14, 'Call Gamma LLC', 'call') ]
if (monthText === current) {
    const today = now.getDate()
    events.push(ev(today, 10, 11, 'Weekly pipeline review', 'meeting'), ev(today, 16, 17, 'Reply to RFQ-2041', 'deadline'))
}
ec.web.sendJsonResponse({ month: monthText, events })
